<?phpnamespace App\Controllers\Admin;use App\Controllers\{AdminController};use App\Models\{Faq, User};use App\Utils\{ Telegram, DatatablesHelper };use App\Services\Mail;use Ozdemir\Datatables\Datatables;use Exception;class FaqController extends AdminController{    public function index($request, $response, $args)    {            $table_config['total_column'] = array(            'op' => '操作',             'id' => 'ID',            'title' => '标题',             'content' => '内容',             'add_time' => '创建时间'        );        $table_config['default_show_column'] = array(            'op',             'id',            'title',            'content',            'add_time'        );                $table_config['ajax_url'] = '/admin/faq/ajax';        return $this->view()->assign('table_config', $table_config)->display('admin/help/faq/index.tpl');    }    public function create($request, $response, $args)    {        return $this->view()->display('admin/help/faq/create.tpl');    }    public function add($request, $response, $args)    {        $title  = $request->getParam('title');        $content = $request->getParam('content');        $markdown = $request->getParam('markdown');        $time  = $request->getParam('time');                if (empty($content) || empty($title) ) {            $rs['ret'] = 0;            $rs['msg'] = '内容不得为空';            return $response->getBody()->write(json_encode($rs));        }                $faq = new Faq();        $faq->title = $title;        $faq->content = $content;        $faq->markdown = $markdown;        $faq->add_time = date('Y-m-d H:i:s');                if (!$faq->save()) {            $rs['ret'] = 0;            $rs['msg'] = '添加失败';            return $response->getBody()->write(json_encode($rs));        }                $rs['ret'] = 1;        $rs['msg'] = '添加成功';        return $response->getBody()->write(json_encode($rs));    }    public function edit($request, $response, $args)    {        $id = $args['id'];        $faq = Faq::find($id);        return $this->view()            ->assign('faq', $faq)            ->display('admin/help/faq/edit.tpl');    }    public function update($request, $response, $args)    {        $title  = $request->getParam('title');        $content = $request->getParam('content');        $markdown = $request->getParam('markdown');        $time  = $request->getParam('time');        $id = $args['id'];        $faq = Faq::find($id);                $faq->title = $title;        $faq->content = $content;        $faq->markdown = $markdown;        $faq->add_time = date('Y-m-d H:i:s');                if (!$faq->save()) {            $rs['ret'] = 0;            $rs['msg'] = '修改失败';            return $response->getBody()->write(json_encode($rs));        }        $rs['ret'] = 1;        $rs['msg'] = '修改成功';        return $response->getBody()->write(json_encode($rs));    }    public function delete($request, $response, $args)    {        $id = $request->getParam('id');        $faq = Faq::find($id);        if (!$faq->delete()) {            $rs['ret'] = 0;            $rs['msg'] = '删除失败';            return $response->getBody()->write(json_encode($rs));        }        $rs['ret'] = 1;        $rs['msg'] = '删除成功';        return $response->getBody()->write(json_encode($rs));    }    public function ajax($request, $response, $args)    {        $datatables = new Datatables(new DatatablesHelper());        $datatables->query('Select id as op,id,title,content,add_time from faq');        $datatables->edit('op', static function ($data) {            return '<a class="btn btn-brand" href="/admin/faq/' . $data['id'] . '/edit">编辑</a>                    <a class="btn btn-brand-accent" id="delete" value="' . $data['id'] . '" href="javascript:void(0);" onClick="delete_modal_show(\'' . $data['id'] . '\')">删除</a>';        });        $datatables->edit('status', static function ($data) {            return $data['status'] == 1 ? '已完成' : '进行中';        });        $body = $response->getBody();        $body->write($datatables->generate());    }}